function wav(seconds=12){const bytes=new Uint8Array(44+24000*2*seconds),v=new DataView(bytes.buffer),put=(at,s)=>{for(let i=0;i<s.length;i++)v.setUint8(at+i,s.charCodeAt(i))};put(0,'RIFF');v.setUint32(4,bytes.length-8,true);put(8,'WAVEfmt ');v.setUint32(16,16,true);v.setUint16(20,1,true);v.setUint16(22,1,true);v.setUint32(24,24000,true);v.setUint32(28,48000,true);v.setUint16(32,2,true);v.setUint16(34,16,true);put(36,'data');v.setUint32(40,bytes.length-44,true);return bytes;}
