function mp4Envelope(){const b=new Uint8Array(256);b.set([102,116,121,112],4);return b;}
function workerMedia(h,owner='alice'){const id=crypto.randomUUID(),bytes=mp4Envelope();h.objects.set(id,bytes);h.sqlite.prepare('INSERT INTO media(id,owner,mime,size,created) VALUES(?,?,?,?,?)').run(id,owner,'video/mp4',bytes.length,Date.now());return id;}
function assemblyParent(h,key,owner='alice'){const id=crypto.randomUUID();h.sqlite.prepare('INSERT INTO reel_jobs(id,owner,status,payload,created,updated,credit_cost) VALUES(?,?,?,?,?,?,?)').run(id,owner,'generating',JSON.stringify({kind:'directed-reel',data:{},steps:[{kind:'assembly',key}],index:0}),Date.now(),Date.now(),0);return id;}
async function assemblyFixture(h){const parts=[workerMedia(h),workerMedia(h)],key='assembly:'+crypto.randomUUID(),parentId=assemblyParent(h,key),job=await h.load('lib/reference-assembly.ts').assemblyAsset('alice',key,parts,[20,21],parentId);return {parts,key,parentId,job};}
function workerRequest(h,method,path,lease,body,headers={}){return new Request('https://jashntoons.test'+path,{method,headers:{authorization:'Bearer '+h.env.MEDIA_WORKER_SECRET,...(lease?{'x-render-lease':lease}:{}),...headers},...(body!==undefined?{body}:{})});}
function workerUpload(h,lease,bytes=mp4Envelope(),headers={}){return workerRequest(h,'PUT','/api/reference-worker/'+lease.id,lease.lease,bytes,{'content-type':'video/mp4','content-length':String(bytes.length),...headers});}
async function assemblyLease(h){const r=await h.load('app/api/reference-worker/lease/route.ts').POST(workerRequest(h,'POST','/api/reference-worker/lease'));assert.equal(r.status,200);return (await r.json()).job;}

test('Assembly leases are exclusive and part access checks token, index, owner and expiry',async()=>{
 const h=harness(),f=await assemblyFixture(h),lr=h.load('app/api/reference-worker/lease/route.ts'),r=h.load('app/api/reference-worker/[id]/route.ts');assert.equal((await lr.POST(workerRequest(h,'POST','/api/reference-worker/lease',null,undefined,{authorization:'wrong'}))).status,401);
 const results=await Promise.all([assemblyLease(h),assemblyLease(h)]),j=results.find(Boolean);assert.equal(results.filter(Boolean).length,1);assert.deepEqual(Object.keys(j).sort(),['id','lease','parts','seconds']);assert.equal(j.parts,2);assert.deepEqual(j.seconds,[20,21]);const c={params:Promise.resolve({id:j.id})},p='/api/reference-worker/'+j.id;
 const part=await r.GET(workerRequest(h,'GET',p+'?part=1',j.lease,undefined,{range:'bytes=0-7'}),c);assert.equal(part.status,206);assert.equal(part.headers.get('cache-control'),'private, no-store');assert.deepEqual(Array.from(new Uint8Array(await part.arrayBuffer())),Array.from(h.objects.get(f.parts[1]).slice(0,8)));
 for(const suffix of ['','?part=-1','?part=1.5','?part=2','?part=bad'])assert.equal((await r.GET(workerRequest(h,'GET',p+suffix,j.lease),c)).status,400);assert.equal((await r.GET(workerRequest(h,'GET',p+'?part=0',crypto.randomUUID()),c)).status,409);
 const value=JSON.parse(h.job(j.id).payload);value.parts[0]=workerMedia(h,'bob');h.sqlite.prepare('UPDATE reel_jobs SET payload=? WHERE id=?').run(JSON.stringify(value),j.id);assert.equal((await r.GET(workerRequest(h,'GET',p+'?part=0',j.lease),c)).status,404);
 h.sqlite.prepare('UPDATE reel_jobs SET updated=? WHERE id=?').run(Date.now()-600001,j.id);const reclaimed=await assemblyLease(h);assert.notEqual(reclaimed.lease,j.lease);assert.equal((await r.GET(workerRequest(h,'GET',p+'?part=1',j.lease),c)).status,409);assert.equal(h.calls.length,0);
});

test('Concurrent assembly results publish once and clean the losing private upload',async()=>{
 const h=harness(),f=await assemblyFixture(h),j=await assemblyLease(h),r=h.load('app/api/reference-worker/[id]/route.ts'),c={params:Promise.resolve({id:j.id})},responses=await Promise.all([r.PUT(workerUpload(h,j),c),r.PUT(workerUpload(h,j),c)]);assert.deepEqual(responses.map(r=>r.status).sort(),[200,409]);const ready=h.job(j.id);assert.equal(ready.status,'ready');assert.ok(h.objects.has(ready.media_id));assert.equal(h.objects.size,f.parts.length+1);assert.equal(h.sqlite.prepare('SELECT COUNT(*) n FROM media').get().n,f.parts.length+1);assert.equal((await r.PUT(workerUpload(h,j),c)).status,409);assert.equal((await r.PATCH(workerRequest(h,'PATCH','/api/reference-worker/'+j.id,j.lease,'{}'),c)).status,409);assert.equal(h.job(j.id).media_id,ready.media_id);
});

test('Slow assembly failure cannot overwrite ready output; malformed PATCH JSON cannot mutate the lease',async()=>{
 const h=harness();await assemblyFixture(h);const j=await assemblyLease(h),r=h.load('app/api/reference-worker/[id]/route.ts'),c={params:Promise.resolve({id:j.id})},p='/api/reference-worker/'+j.id;
 for(const body of ['{broken','[]','null','"invalid"']){assert.equal((await r.PATCH(workerRequest(h,'PATCH',p,j.lease,body,{'content-type':'application/json'}),c)).status,400);assert.equal(h.job(j.id).status,'processing');}
 let started,release;const entered=new Promise(resolve=>started=resolve),gate=new Promise(resolve=>release=resolve);h.onJsonRead(async req=>{if(req.method==='PATCH'){started();await gate;}});const pending=r.PATCH(workerRequest(h,'PATCH',p,j.lease,'{}'),c);await entered;assert.equal((await r.PUT(workerUpload(h,j),c)).status,200);const id=h.job(j.id).media_id;release();assert.equal((await pending).status,409);assert.equal(h.job(j.id).status,'ready');assert.equal(h.job(j.id).media_id,id);assert.ok(h.objects.has(id));
});

test('Invalid, truncated, oversized or late assembly results leave no published or orphan output',async()=>{
 const h=harness(),f=await assemblyFixture(h),j=await assemblyLease(h),r=h.load('app/api/reference-worker/[id]/route.ts'),c={params:Promise.resolve({id:j.id})};for(const [req,status] of [[workerUpload(h,j,mp4Envelope(),{'content-type':'video/webm'}),400],[workerUpload(h,j,mp4Envelope(),{'content-length':''}),400],[workerUpload(h,j,mp4Envelope(),{'content-length':'80000001'}),413],[workerUpload(h,j,mp4Envelope(),{'content-length':'512'}),400],[workerUpload(h,j,new Uint8Array(256)),400]]){assert.equal((await r.PUT(req,c)).status,status);assert.equal(h.job(j.id).status,'processing');assert.equal(h.objects.size,f.parts.length);assert.equal(h.sqlite.prepare('SELECT COUNT(*) n FROM media').get().n,f.parts.length);}
 h.onStore(()=>h.sqlite.prepare('UPDATE reel_jobs SET updated=? WHERE id=?').run(Date.now()-600001,j.id));assert.equal((await r.PUT(workerUpload(h,j),c)).status,409);assert.equal(h.job(j.id).media_id,null);assert.equal(h.objects.size,f.parts.length);assert.equal(h.sqlite.prepare('SELECT COUNT(*) n FROM media').get().n,f.parts.length);
});

test('Assembly storage and insert failures clean output, but a lost commit acknowledgement preserves success',async()=>{
 for(const fault of ['storage','insert','commit-ack']){const h=harness(),f=await assemblyFixture(h),j=await assemblyLease(h),r=h.load('app/api/reference-worker/[id]/route.ts'),c={params:Promise.resolve({id:j.id})};let tripped=false;
 if(fault==='storage')h.onStore(()=>{if(!tripped){tripped=true;throw Error('Simulated storage failure');}});else{const prepare=h.env.DB.prepare;h.env.DB.prepare=sql=>{const statement=prepare(sql);return {bind(...args){const b=statement.bind(...args);return {...b,run:async()=>{if(!tripped&&fault==='insert'&&sql.startsWith('INSERT INTO media')){tripped=true;throw Error('Simulated insert failure');}const out=await b.run();if(!tripped&&fault==='commit-ack'&&sql.startsWith('UPDATE reel_jobs SET media_id=')){tripped=true;throw Error('Simulated acknowledgement failure');}return out;}}}};};}
 const response=await r.PUT(workerUpload(h,j),c);assert.equal(tripped,true);if(fault==='commit-ack'){assert.equal(response.status,200);assert.equal(h.job(j.id).status,'ready');assert.ok(h.objects.has(h.job(j.id).media_id));assert.equal(h.objects.size,f.parts.length+1);}else{assert.equal(response.status,500);assert.equal(h.job(j.id).status,'processing');assert.equal(h.objects.size,f.parts.length);assert.equal(h.sqlite.prepare('SELECT COUNT(*) n FROM media').get().n,f.parts.length);}}
});

test('Failed assembly needs a new owned parent to retry locally without provider work or repeated same-parent joins',async()=>{
 const h=harness(),f=await assemblyFixture(h),service=h.load('lib/reference-assembly.ts'),j=await assemblyLease(h),r=h.load('app/api/reference-worker/[id]/route.ts'),c={params:Promise.resolve({id:j.id})};assert.equal((await r.PATCH(workerRequest(h,'PATCH','/api/reference-worker/'+j.id,j.lease,'{"error":"private worker details"}'),c)).status,200);assert.equal(h.job(j.id).status,'failed');assert.doesNotMatch(h.job(j.id).error,/private worker details/);
 const same=await service.assemblyAsset('alice',f.key,f.parts,[20,21],f.parentId);assert.equal(same.status,'failed');assert.equal(JSON.parse(same.payload).attempts,1);const foreign=assemblyParent(h,f.key,'bob');await assert.rejects(service.assemblyAsset('alice',f.key,f.parts,[20,21],foreign),e=>e.status===403);
 const parent=assemblyParent(h,f.key),retry=await service.assemblyAsset('alice',f.key,f.parts,[20,21],parent);assert.equal(retry.id,j.id);assert.equal(retry.status,'queued');assert.equal(retry.provider_task,null);assert.equal(JSON.parse(retry.payload).attempts,0);assert.equal(JSON.parse(retry.payload).retryParent,parent);const next=await assemblyLease(h);assert.notEqual(next.lease,j.lease);assert.equal((await r.PUT(workerUpload(h,j),c)).status,409);assert.equal((await r.PUT(workerUpload(h,next),c)).status,200);assert.equal(h.calls.length,0);assert.equal((await h.load('lib/credits.ts').balance('alice')).used,0);
});

test('Assembly validates owned parts and finite timing, bounds lease attempts, and ignores unrelated malformed records',async()=>{
 const h=harness(),part=workerMedia(h),foreign=workerMedia(h,'bob'),image=h.photo(),service=h.load('lib/reference-assembly.ts');for(const parts of [[foreign],[image],[crypto.randomUUID()]])await assert.rejects(service.assemblyAsset('alice','bad:'+crypto.randomUUID(),parts,[20]),e=>e.status===404);
 for(const [parts,seconds] of [[[part],[NaN]],[[part],[Infinity]],[[part],['20']],[[part],[2]],[[part],[31]],[[part],[]],[['bad'],[20]]])await assert.rejects(service.assemblyAsset('alice','bad:'+crypto.randomUUID(),parts,seconds),e=>e.status===400);
 const queued=await service.assemblyAsset('alice','attempt-test',[part],[20]),bad=crypto.randomUUID();h.sqlite.prepare('INSERT INTO reel_jobs(id,owner,status,payload,created,updated,credit_cost) VALUES(?,?,?,?,?,?,?)').run(bad,'alice','generating','{broken',Date.now(),Date.now(),0);const tick=await h.load('app/api/reference-worker/tick/route.ts').POST(workerRequest(h,'POST','/api/reference-worker/tick'));assert.equal(tick.status,200);assert.equal((await tick.json()).checked,0);
 let lease=await assemblyLease(h);assert.equal(lease.id,queued.id);for(let attempt=2;attempt<=3;attempt++){h.sqlite.prepare('UPDATE reel_jobs SET updated=? WHERE id=?').run(Date.now()-600001,queued.id);lease=await assemblyLease(h);assert.ok(lease);assert.equal(JSON.parse(h.job(queued.id).payload).attempts,attempt);}h.sqlite.prepare('UPDATE reel_jobs SET updated=? WHERE id=?').run(Date.now()-600001,queued.id);assert.equal(await assemblyLease(h),null);assert.equal(h.job(queued.id).status,'failed');assert.ok(h.objects.has(part));assert.equal(h.calls.length,0);
});

function harness(){
 const sqlite=new DatabaseSync(':memory:');for(const f of fs.readdirSync(path.join(root,'drizzle')).filter(f=>f.endsWith('.sql')).sort())sqlite.exec(fs.readFileSync(path.join(root,'drizzle',f),'utf8'));
 const objects=new Map(),calls=[],globals={},headCalls=[],assemblies=[],taskResults=new Map();let user='alice',failAt='',failStatus=400,outcome='SUCCEEDED',failureCode,referenceTask=0,storeHook,jsonReadHook;
 const env={RUNWAY_API_KEY:'test-only',MEDIA_WORKER_ENABLED:'1',MEDIA_WORKER_SECRET:'test-only-worker-secret-1234567890',DB:{prepare(sql){return {bind(...args){return {first:async()=>sqlite.prepare(sql).get(...args)||null,all:async()=>({results:sqlite.prepare(sql).all(...args)}),run:async()=>({meta:{changes:Number(sqlite.prepare(sql).run(...args).changes)}})}}}}},BUCKET:{put:async(id,data)=>{const bytes=data instanceof Uint8Array?data:new Uint8Array(await new Response(data).arrayBuffer());objects.set(id,bytes);if(storeHook)await storeHook(id,bytes);return {size:bytes.length};},get:async(id,options)=>{if(!objects.has(id))return null;const stored=objects.get(id),bytes=options?.range?stored.slice(options.range.offset,options.range.offset+options.range.length):stored;return {body:bytes,arrayBuffer:async()=>bytes.buffer.slice(bytes.byteOffset,bytes.byteOffset+bytes.byteLength)}},head:async id=>{headCalls.push(id);return objects.has(id)?{key:id,size:objects.get(id).length}:null},delete:async(id)=>objects.delete(id)}};
 class APIError extends Error{constructor(status,message){super(message);this.status=status}}
 const api={APIError,identity:async()=>{if(!user)throw new APIError(401,'Sign in');return {userId:user}},originCheck:r=>{if(r.headers.get('origin')!=='https://jashntoons.test')throw new APIError(403,'Origin')},json:(v,status=200)=>Response.json(v,{status}),smallJson:async r=>{if(jsonReadHook)await jsonReadHook(r);try{return await r.json()}catch{throw new APIError(400,'Invalid request.')}},boundedBytes:async(r,max)=>{const b=new Uint8Array(await r.arrayBuffer());if(b.length>max)throw new APIError(413,'Too large');return b},guarded:async fn=>{try{return await fn()}catch(e){if(e instanceof APIError)return Response.json({error:e.message},{status:e.status});return Response.json({error:'Something went wrong.'},{status:500})}}};
 const fetch=async(url,options={})=>{const body=options.body?JSON.parse(options.body):undefined;calls.push({url,body,headers:options.headers});if(failAt&&url.includes(failAt))return new Response('{}',{status:failStatus});
  if(url.endsWith('/voices')&&body)return Response.json({id:'voice-remote',status:'PROCESSING'});
  if(url.includes('/voices/'))return Response.json({id:'voice-remote',status:'READY'});
  if(url.endsWith('/text_to_image'))return Response.json({id:'art-task'});
  if(url.endsWith('/image_to_video'))return Response.json({id:'film-task'});
  if(url.endsWith('/video_to_video'))return Response.json({id:'reference-task-'+(++referenceTask)});
  if(url.endsWith('/text_to_speech'))return Response.json({id:'speech-task'});
  if(url.endsWith('/avatars')&&body)return Response.json({id:'avatar-remote',status:'AvatarProcessing'});
  if(url.includes('/avatars/'))return Response.json({id:'avatar-remote',status:'AvatarReady'});
  if(url.endsWith('/avatar_videos'))return Response.json({id:'video-task'});
  if(url.includes('/tasks/')){const taskId=url.split('/').at(-1),result=taskResults.get(taskId);return Response.json({id:taskId,status:result?.status??outcome,failureCode:result?.failureCode??failureCode,output:[url.endsWith('speech-task')?'https://output.test/voice.mp3':url.endsWith('art-task')?'https://output.test/art.png':'https://output.test/'+taskId+'.mp4']});}
  if(url.startsWith('/api/media'))return new Response(new Uint8Array([1,2,3]));
  if(url.endsWith('.png'))return new Response(new Uint8Array([137,80,78,71]),{headers:{'content-type':'image/png'}});
  if(url.endsWith('.mp3'))return new Response(new Uint8Array([73,68,51]),{headers:{'content-type':'audio/mpeg'}});
  if(url.endsWith('.mp4'))return new Response(new Uint8Array([1,2,3]),{headers:{'content-type':'video/mp4'}});
  throw Error('Unexpected fetch '+url);
 };
 const cache=new Map();function load(file){file=path.resolve(root,file);if(cache.has(file))return cache.get(file);const module={exports:{}};cache.set(file,module.exports);const compiled=ts.transpileModule(fs.readFileSync(file,'utf8'),{compilerOptions:{module:ts.ModuleKind.CommonJS,target:ts.ScriptTarget.ES2022}}).outputText;
 vm.runInNewContext(compiled,{module,exports:module.exports,require(name){if(name==='./studio-score')return {studioScore:async duration=>({duration})};if(name==='cloudflare:workers')return {env};if(name.endsWith('/api')||name==='./api')return api;if(name.startsWith('@/'))return load(name.slice(2)+'.ts');if(name.startsWith('.'))return load(path.relative(root,path.resolve(path.dirname(file),name+'.ts')));return require(name)},console,crypto,URL,TextEncoder,TextDecoder,Uint8Array,ArrayBuffer,DataView,Response,Request,Headers,File,FormData,AbortSignal,Date,Math,Set,Number,JSON,Error,btoa,atob,fetch,setTimeout,clearTimeout,...globals},{filename:file});return module.exports}
 const job=id=>sqlite.prepare('SELECT * FROM reel_jobs WHERE id=?').get(id),voice=()=>load('lib/voice-studio.ts'),advance=id=>voice().advanceVoice(job(id));
 function fund(credits=100){sqlite.prepare('INSERT INTO credit_grants VALUES(?,?,?,?)').run(crypto.randomUUID(),'alice',credits,Date.now())}
 function photo(){const id=crypto.randomUUID();objects.set(id,new Uint8Array([137,80,78,71]));sqlite.prepare('INSERT INTO media(id,owner,mime,size,created) VALUES(?,?,?,?,?)').run(id,'alice','image/png',4,Date.now());return id}
 function project(){const id=crypto.randomUUID();sqlite.prepare('INSERT INTO projects VALUES(?,?,?,?,?)').run(id,'alice','Invite','{}',Date.now());return id}
 const sample={name:'My voice',bytes:new Uint8Array([1,2,3]),consent:true,approveCredits:1};
 async function readyVoice(){const v=await voice().createVoice('alice',sample);await advance(v.id);return v.id}
 function prepareSource(source){const contract=load('lib/reference-edit-contract.ts');for(const segment of source.segments)objects.set(contract.referenceAssetKey(source.id,contract.referenceAssetName(segment.index)),new Uint8Array([1,2,3]));}
 // Only emulate the worker persistence after the real director queues an assembly.
 function completeAssemblies(){for(const row of sqlite.prepare("SELECT * FROM reel_jobs WHERE status='queued' AND json_extract(payload,'$.kind')='reference-assembly'").all()){const p=JSON.parse(row.payload);assert.equal(p.parts.length,p.seconds.length);for(const part of p.parts){const media=sqlite.prepare('SELECT * FROM media WHERE id=? AND owner=?').get(part,row.owner);assert.equal(media?.mime,'video/mp4');assert.ok(objects.has(part));}const id=crypto.randomUUID();objects.set(id,new Uint8Array([1,2,3]));sqlite.prepare('INSERT INTO media(id,owner,mime,size,created) VALUES(?,?,?,?,?)').run(id,row.owner,'video/mp4',3,Date.now());sqlite.prepare("UPDATE reel_jobs SET status='ready',media_id=?,updated=? WHERE id=?").run(id,Date.now(),row.id);assemblies.push({id:row.id,...p});}}
 return {globals,env,sqlite,objects,calls,headCalls,assemblies,load,job,advance,fund,photo,project,sample,readyVoice,prepareSource,completeAssemblies,onStore:hook=>storeHook=hook,onJsonRead:hook=>jsonReadHook=hook,taskOutcome:(id,status,code)=>taskResults.set(id,{status,failureCode:code}),setUser:v=>user=v,fail:(v,status=400)=>{failAt=v;failStatus=status},outcome:(v,code)=>{outcome=v;failureCode=code}};
}


test('Regenerate makes a new film only after approval, keeps the completed original, and retries without another charge',async()=>{
 const h=harness();h.fund();const service=h.load('lib/creation-jobs.ts'),{data,projectId}=fixture(h,'recording'),q=await service.quoteCreation('alice',data),job=await service.startCreation('alice',projectId,data,q),done=await finish(h,job.id),saved=h.load('lib/director-contract.ts').applyDirectedReel(data,done.result),library=h.load('lib/reel-library.ts');
 const draft=library.regenerationDraft(saved);assert.ok(library.readyToFinish(saved));assert.equal(library.readyToFinish({...saved,pendingCreationId:crypto.randomUUID()}),false);assert.equal(library.readyToFinish(data),false);
 const calls=h.calls.length,used=(await h.load('lib/credits.ts').balance('alice')).used,next=await service.quoteCreation('alice',draft);assert.equal(h.calls.length,calls);assert.equal((await h.load('lib/credits.ts').balance('alice')).used,used);assert.equal(next.credits,7);assert.equal(draft.creation.audioId,saved.creation.audioId);
 await assert.rejects(service.startCreation('alice',projectId,draft,{key:next.key,credits:0}),e=>e.status===409);
 const second=await service.startCreation('alice',projectId,draft,next),ready=await finish(h,second.id);assert.notEqual(ready.result.videoId,done.result.videoId);assert.equal(ready.result.artId,done.result.artId);assert.equal(h.calls.filter(c=>c.url.endsWith('/text_to_image')).length,1);assert.equal(h.calls.filter(c=>c.url.endsWith('/image_to_video')).length,2);assert.equal(h.job(job.id).status,'ready');assert.equal(JSON.parse(h.job(job.id).payload).result.videoId,saved.generatedVideo);
 const retry=await service.quoteCreation('alice',draft);assert.equal(retry.credits,0);assert.equal((await service.startCreation('alice',projectId,draft,retry)).id,second.id);assert.equal((await h.load('lib/credits.ts').balance('alice')).used,15);
});
